'use strict';
/**
 * enrich.js — a card's short Japanese title, what it is doing and waiting on,
 * generated by `claude -p --model haiku` from a small fragment of the
 * session's transcript. Cached in ~/.rally/titles.json (misses too, as
 * `fail: true`); Claude/codex top-level sessions only, a few calls per refresh.
 */
const Env = require('./env.js');
const Names = require('./names.js');
const fs = require('fs');
const os = require('os');
const path = require('path');
const Fsx = require('./fsx.js');
const { spawn, spawnSync } = require('child_process');
const Paths = require('./paths.js');
const Dispatch = require('./dispatch.js');
const LastMessage = require('./lastMessage.js');

const NAME = 'rally';
const PENDING_TIMEOUT_MS = 5 * 60000; // a stuck/killed child stops blocking retries after this
const DEFAULT_BATCH = 1;
const REFRESH_BYTES = 40 * 1024;
const REFRESH_MS = 10 * 60000;
// bump when the prompt changes: a title written under an older version is stale
const PROMPT_V = 4;

const FAIL_RETRY_MS = 60 * 60 * 1000;
function cachePath() { return Env.get('TITLES') || Paths.akDir('titles.json'); }
function readCache() { try { return JSON.parse(fs.readFileSync(cachePath(), 'utf8')); } catch (e) { return {}; } }
// atomic: a torn read would reset the whole cache to {}
function writeCache(c) {
  Fsx.writeJSONAtomic(cachePath(), c);
}
// read-modify-write one key, keeping the race with concurrent children short
function setKey(k, value) {
  const c = readCache();
  c[k] = value;
  writeCache(c);
  return c;
}
function key(agent, id) { return `${agent}:${id}`; }

/**
 * The titles Claude Code keeps in the transcript's tail: {custom (/rename),
 * agent (the session name other clients show), ai}. A derived name like
 * "me-af" (folder + two hex digits) is a placeholder, not a title.
 */
function ownTitles(file) {
  let text = '';
  try {
    const fd = fs.openSync(file, 'r');
    try { const size = fs.fstatSync(fd).size, n = Math.min(size, 512 * 1024); const b = Buffer.alloc(n); fs.readSync(fd, b, 0, n, size - n); text = b.toString('utf8'); }
    finally { fs.closeSync(fd); }
  } catch (e) { return {}; }
  const last = (re) => { let m, v = ''; while ((m = re.exec(text))) v = m[1]; return v; };
  const un = (x) => { try { return JSON.parse('"' + x + '"'); } catch (e) { return x; } };
  const custom = last(/"customTitle":"((?:[^"\\]|\\.)*)"/g), ai = last(/"type":"ai-title","aiTitle":"((?:[^"\\]|\\.)*)"/g);
  // only the name records themselves: a peer message carries an agentName too (the sender's first ask)
  let agent = last(/"type":"agent-name","agentName":"((?:[^"\\]|\\.)*)"/g);
  if (agent && /^[\w.-]+-[0-9a-f]{2}$/.test(un(agent))) agent = '';
  return { custom: custom ? un(custom).slice(0, 60) : '', agent: agent ? un(agent).slice(0, 60) : '', ai: ai ? un(ai).slice(0, 60) : '' };
}

/** Attach any settled {title, waiting} onto cards. Cheap: one small JSON read, no process spawned. */
function applyCached(cards, fileOf = (c) => c.file) {
  const cache = readCache();
  for (const c of cards) {
    const v = cache[key(c.agent, c.id)];
    // waitingLine: the pass's one line on what it is stuck on — not `waiting`, which is the lane's whose-move (you / agent / permission)
    if (v && !v.pending && !v.fail) { c.title = v.title || null; c.doingLine = v.doing || null; c.waitingLine = v.waiting || null; c.titleAt = v.at || null; c.icon = v.icon || null; }
    // a title being re-read keeps its icon meanwhile
    else if (v && v.pending && v.icon) c.icon = v.icon;
    // one name everywhere: /rename, then Claude Code's own name, then the board's.
    // Subagents and headless runs keep their own titles.
    const f = c.agent === 'claude' && !c.subagent && !c.headless ? fileOf(c) : null;
    if (f) {
      const t = ownTitles(f);
      if (c.title) c.boardTitle = c.title;
      if (t.custom) { c.title = t.custom; c.titleFrom = 'rename'; }
      else if (t.agent || t.ai) { c.title = t.agent || t.ai; c.titleFrom = 'claude'; }
    }
  }
  return cache;
}

/** Has this session moved far enough since its title to be worth re-reading? */
function stale(v, size, now = Date.now()) {
  if (!v || v.pending) return false;
  // a failure is retried after FAIL_RETRY_MS once the transcript grew (or much later regardless)
  if (v.fail) return now - (v.at || 0) >= FAIL_RETRY_MS && (!v.size || !size || size > v.size || now - (v.at || 0) >= 6 * FAIL_RETRY_MS);
  if ((v.v || 1) !== PROMPT_V) return true;                 // written under an older rule
  // named once from the opening asks and kept; only one named from fewer than three is re-read
  if ((v.n || 0) >= 3) return false;
  if (!size || !v.size) return false;
  return size - v.size >= 8 * 1024;
}

/** The fragment the model names: the opening asks, the last reply, what it touched. */
function fragmentFrom(msg, lastTool, opts = {}) {
  const parts = [];
  const human = msg && msg.human;
  const first = msg && msg.first;
  if (opts.project) parts.push(`作業場所=「${opts.project}」`);
  const asks = (opts.asks || []).filter(Boolean);
  if (asks.length) parts.push(`最初の依頼(古い順)=「${asks.join('」「')}」`);
  else if (human) parts.push(`最後の依頼=「${human}」`);
  if (opts.exchanges) parts.push(`やり取り=${opts.exchanges}回`);
  if (msg && msg.assistant) parts.push(`直前の応答=「${msg.assistant}」`);
  const targets = (opts.targets || []).filter(Boolean).slice(0, 6);
  if (targets.length) parts.push(`最近さわった対象=「${targets.join(', ')}」`);
  const tools = (opts.recentTools || []).filter(Boolean).slice(0, 5);
  if (tools.length) parts.push(`最近のツール=「${tools.join(', ')}」`);
  else if (lastTool) parts.push(`直前のツール=「${lastTool}」`);
  if (first && first !== human && !asks.length) parts.push(`最初の依頼(古い・参考)=「${first}」`);
  return parts.join(' ');
}

const PROMPT_HEAD = `次のセッション断片を読んで、JSONだけを返してください。説明も前置きも不要です。
title: このセッションが何のためのものかを表す日本語の題名。14文字以内。
  **最初の依頼から読み取れる目的**を書く。個別の修正や細部ではなく主題を。
  例: 「送信ボタンの不具合修正」ではなく「Rally改良」、「CSVの列名変更」ではなく「請求データ移行」。
  作業場所(リポジトリ名)と繰り返し出てくる対象から、何のための作業かを推測する。
  ファイル名やハッシュやURLをそのまま使わない。
doing: いま(直近で)具体的に何をしているか・していたか。日本語30文字以内。対象を名指しする。
  例: 「送信欄のEnter処理を修正し、テストを実行中」。「作業中」「対応中」だけのような中身のない言葉は禁止。
waiting: 何を待って止まっているか。誰の・何の判断や入力か、何が返ってくるのを待つのかを具体的に。日本語30文字以内。
  例: 「PR #12 をマージしてよいかのあなたの判断」「本番DBの接続情報の共有」。「あなたの返事待ち」のような言い換えは禁止。
  止まっていなければ次の一手。分からなければ空文字。
icon: title の主題に近い絵文字を1つだけ。
{"title":"...","doing":"...","waiting":"...","icon":"..."}

断片: `;

/** ```json … ``` fences and any leading/trailing prose around the object. */
function parseResult(text) {
  const s = String(text || '').indexOf('{'), e = String(text || '').lastIndexOf('}');
  if (s === -1 || e === -1 || e < s) return null;
  let j; try { j = JSON.parse(text.slice(s, e + 1)); } catch (err) { return null; }
  if (!j || typeof j.title !== 'string' || !j.title) return null;
  return { title: j.title.slice(0, 40), doing: typeof j.doing === 'string' ? j.doing.slice(0, 60) : '', waiting: typeof j.waiting === 'string' ? j.waiting.slice(0, 60) : '', icon: iconOf(j.icon) };
}

/** The first emoji (with its joiners) in the model's answer, or null. */
function iconOf(v) {
  const s = String(v || '').trim();
  const m = /(\p{Extended_Pictographic}(?:\uFE0F|\u20E3|\p{Emoji_Modifier}|\u200D\p{Extended_Pictographic}\uFE0F?)*)/u.exec(s);
  return m ? m[1] : null;
}

// No tools (`--tools ""`): the prompt holds untrusted transcript text, so a tool
// would be a prompt-injection path. The prompt follows `--` since --tools is variadic.
const HEADLESS = ['-p', '--model', 'haiku', '--output-format', 'json', '--no-session-persistence', '--setting-sources', 'project', '--tools', ''];

const ICON_PROMPT = `次の作業の題名に内容が近い絵文字を1つだけ返してください。絵文字以外は何も書かないでください。
題名: `;

/** An icon for a title that has none: only the title is sent, and it is kept as is. */
function runIcon({ agent, id }) {
  const k = key(agent, id);
  const v = readCache()[k];
  if (!v || !v.title || v.icon) return v && v.icon || null;
  const claudeBin = Dispatch.binaryFor('claude');
  let icon = null;
  if (claudeBin) {
    let out;
    try { out = spawnSync(claudeBin, [...HEADLESS, '--', ICON_PROMPT + v.title], { encoding: 'utf8', timeout: 45000, cwd: os.tmpdir() }); }
    catch (e) { out = null; }
    if (out && out.status === 0 && out.stdout) {
      let o; try { o = JSON.parse(out.stdout); } catch (e) { o = null; }
      if (o && o.is_error !== true && typeof o.result === 'string') icon = iconOf(o.result);
    }
  }
  // re-read: the title may have been rewritten while the call ran
  const now = readCache()[k] || {};
  setKey(k, icon ? { ...now, icon, iconPending: undefined } : { ...now, iconFail: Date.now(), iconPending: undefined });
  return icon;
}

/** Reads the file, calls the model, writes the cache. Runs in the detached child (spawnEnricher). */
function runOne({ agent, id, file, lastTool, recentTools, targets, project }) {
  const k = key(agent, id);
  let size = 0;
  try { size = fs.statSync(file).size; } catch (e) { /* unmeasured */ }
  const msg = LastMessage.lastMessage({ agent, file });
  let asks = [], exchanges = 0, asksN = 0;
  try {
    const h = LastMessage.history({ agent, file }, { maxTurns: 400 });
    const users = ((h && h.turns) || []).filter((t) => t.kind === 'user')
      .map((t) => String(t.text || '').replace(/\s+/g, ' ').slice(0, 90))
      .filter((t) => t && !Names.LINE_RE.test(t));
    exchanges = Math.min(users.length, 3);
    // the opening asks say what the session is for; later turns are details
    asks = users.slice(0, 3);
    asksN = asks.length;
  } catch (e) { /* the one-line fallback below still works */ }
  const fragment = msg ? fragmentFrom(msg, lastTool, { recentTools, asks, targets, project, exchanges }) : '';
  if (!fragment) { setKey(k, { fail: true, at: Date.now(), size }); return null; }
  const claudeBin = Dispatch.binaryFor('claude'); // both fragments are summarised by claude/haiku, regardless of the source agent
  let result = null;
  if (claudeBin) {
    let out;
    // --no-session-persistence: the lookup must not appear on the board as a session.
    // --setting-sources project: skip the user's hooks (a SessionStart hook per call
    //   can be expensive); --bare would need an API key. cwd = tmpdir: no CLAUDE.md.
    try { out = spawnSync(claudeBin, [...HEADLESS, '--', PROMPT_HEAD + fragment], { encoding: 'utf8', timeout: 45000, cwd: os.tmpdir() }); }
    catch (e) { out = null; }
    if (out && out.status === 0 && out.stdout) {
      let o; try { o = JSON.parse(out.stdout); } catch (e) { o = null; }
      if (o && o.is_error !== true && typeof o.result === 'string') result = parseResult(o.result);
    }
  }
  setKey(k, result ? { title: result.title, doing: result.doing, waiting: result.waiting, icon: result.icon, at: Date.now(), size, v: PROMPT_V, n: asksN }
    : { fail: true, at: Date.now(), size, v: PROMPT_V });
  return result;
}

function spawnEnricher(c, iconOnly) {
  const script = path.join(__dirname, '..', 'bin', 'rally.js');
  const args = iconOnly ? [script, 'enrich', '--icon', '--as', c.agent, '--session', c.id] : [script, 'enrich', '--as', c.agent, '--session', c.id, '--file', c.file || '', '--last-tool', c.lastTool || '',
    '--tools', (c.recentTools || []).slice(0, 5).join(','),
    '--targets', (c.targets || []).slice(0, 6).join('|'), '--project', c.project || ''];
  try {
    const child = spawn(process.execPath, args, { detached: true, stdio: 'ignore' });
    child.unref();
  } catch (e) { /* no node at this path — next refresh tries again */ }
}

// bounds on haiku calls: children alive at once, and spawns per hour across refreshes
const MAX_INFLIGHT = 3;
const HOURLY_CAP = 40;
function spawnLogPath() { return Env.get('ENRICH_LOG') || path.join(path.dirname(cachePath()), 'enrich-spawns.json'); }
function spawnsWithin(now, ms = 3600000) {
  try { return (JSON.parse(fs.readFileSync(spawnLogPath(), 'utf8')) || []).filter((t) => now - t < ms); } catch (e) { return []; }
}
function noteSpawns(now, n) {
  if (!n) return;
  const f = spawnLogPath();
  const list = spawnsWithin(now).concat(Array(n).fill(now));
  try { Fsx.writeJSONAtomic(f, list, undefined, 0); } catch (e) { /* the cap is best effort */ }
}
/** Children still running: a fresh pending title or icon mark. */
function inflight(cache, now) {
  let n = 0;
  for (const v of Object.values(cache || {})) {
    if (!v || typeof v !== 'object') continue;
    if (v.pending && now - (v.at || 0) < PENDING_TIMEOUT_MS) n++;
    if (v.iconPending && now - v.iconPending < PENDING_TIMEOUT_MS) n++;
  }
  return n;
}

/**
 * Start background enrichment for cards (newest first) lacking a title or icon;
 * results land in the cache for a later refresh. Order: untitled, then due a
 * re-read, then icon-only. Bounded by batch/iconBatch, MAX_INFLIGHT, HOURLY_CAP.
 * @returns {number} how many were started
 */
function enrichSome(candidates, opts = {}) {
  // each key is marked with its own read-modify-write just before spawning, not from this snapshot
  const cache = readCache();
  const now = opts.now || Date.now();
  const batch = opts.batch || DEFAULT_BATCH;
  const iconBatch = opts.iconBatch != null ? opts.iconBatch : batch;
  const spawnFn = opts.spawn || spawnEnricher;
  const room = Math.min((opts.maxInflight || MAX_INFLIGHT) - inflight(cache, now), (opts.hourlyCap || HOURLY_CAP) - spawnsWithin(now).length);
  if (room <= 0) return 0;
  const jobs = [];   // {c, rank, icon}
  for (const c of candidates) {
    if (c.agent !== 'claude' && c.agent !== 'codex') continue;
    if (c.subagent) continue;
    if (!c.file) continue;
    const k = key(c.agent, c.id);
    const v = cache[k];
    let size = 0;
    try { size = fs.statSync(c.file).size; } catch (e) { /* gone: treat as unmeasured */ }
    const settled = v && !v.pending;
    // an old entry with no size: record it now rather than regenerate
    if (settled && !v.size && size && (v.v || 1) === PROMPT_V) { setKey(k, { ...v, size }); continue; }
    if (settled && !stale(v, size, now)) {
      // no icon yet: a title-only call (a failed try waits FAIL_RETRY_MS)
      if (v.title && !v.icon && !(v.iconPending && now - v.iconPending < PENDING_TIMEOUT_MS) && !(v.iconFail && now - v.iconFail < FAIL_RETRY_MS)) jobs.push({ c, k, rank: 2, icon: true });
      continue;
    }
    if (v && v.pending && now - v.at < PENDING_TIMEOUT_MS) continue;    // another run is in flight
    jobs.push({ c, k, size, v, rank: v && v.title ? 1 : 0 });
  }
  jobs.sort((a, b) => a.rank - b.rank);   // stable: newest first within a rank
  let started = 0, titles = 0, icons = 0;
  for (const j of jobs) {
    if (started >= room) break;
    if (j.icon) {
      if (icons >= iconBatch) continue;
      setKey(j.k, { ...(readCache()[j.k] || {}), iconPending: now });
      icons++; started++;
      spawnFn(j.c, true);
      continue;
    }
    if (titles >= batch) continue;
    setKey(j.k, { pending: true, at: now, size: j.size, prev: j.v && j.v.title ? j.v.title : null, icon: j.v && j.v.icon || undefined });
    titles++; started++;
    spawnFn(j.c);
  }
  noteSpawns(now, started);
  return started;
}

module.exports = { HEADLESS, MAX_INFLIGHT, HOURLY_CAP, inflight, spawnsWithin, iconOf, runIcon, cachePath, readCache, writeCache, applyCached, ownTitles, FAIL_RETRY_MS, enrichSome, fragmentFrom, parseResult, runOne, stale, REFRESH_BYTES, REFRESH_MS, PROMPT_V };
